def _verify_gateway_result(port, fault, hashes, model):
    """执行扫描/触发并按 fault 类型核对阶段、错误码、串口零擦写与终态。"""
    assert request(port, 'trigger')[0] == 405
    assert request(port, 'trigger', {'target': 'both', 'confirmed_safe': False})[0] == 400
    assert split_request(port, '{"target":"both","target":"mc"}')[0] == 400
    assert split_request(port, '{"target":"both","confirmed_safe":"true"}')[0] == 400
    assert split_request(port, '{"target":"both"}trailing')[0] == 400
    code, accepted = split_request(port, '{"target":"both"}')
    assert code == 202, accepted
    ready = wait_status(port, accepted['task_id'], ['READY', 'FAILED'], model)
    if fault in ('unsigned_zero', 'bad_signature', 'tampered_payload', 'missing_pubkey'):
        assert ready['phase'] == 'FAILED' and ready['error'] == 'PACKAGE_SIGNATURE_INVALID', ready
        assert not any(cmd in (0x1d, 0x20) for _, cmd in model.commands), model.commands
        trig = {'target': 'both', 'confirmed_safe': True, 'allow_reflash': True,
                'mc_sha256': hashes[2], 'th_sha256': hashes[3]}
        code2, acc2 = request(port, 'trigger', trig)
        assert code2 == 202, acc2
        res2 = wait_status(port, acc2['task_id'], ['SUCCEEDED', 'FAILED'], model)
        assert res2['phase'] == 'FAILED' and res2['error'] == 'PACKAGE_SIGNATURE_INVALID', res2
        assert not any(cmd in (0x1d, 0x20) for _, cmd in model.commands), model.commands
        return res2
    assert ready['phase'] == 'READY' and ready['mc']['sha256'] == hashes[2] and ready['th']['sha256'] == hashes[3]
    assert not any(cmd in (0x1d, 0x20) for _, cmd in model.commands)
    start = {'target': 'both', 'confirmed_safe': True, 'allow_reflash': True,
             'mc_sha256': hashes[2], 'th_sha256': hashes[3]}
    if fault == 'hash': start['th_sha256'] = '0' * 64
    code, accepted = request(port, 'trigger', start)
    assert code == 202, accepted
    if fault != 'hash': assert request(port, 'trigger', start)[0] == 409
    result = wait_status(port, accepted['task_id'], ['SUCCEEDED', 'FAILED'], model)
    _assert_ota_outcome(port, fault, result, model)
    return result


def _assert_ota_outcome(port, fault, result, model):
    """断言升级成功或确定性通信/校验故障的终态与串口隔离约束。"""
    comm_faults = ('preflight_timeout', 'preflight_delayed', 'heater_timeout',
                   'boot_timeout', 'post_temperature_timeout', 'disconnect')
    if fault in ('hash', 'status', 'identity', 'boot_identity') + comm_faults:
        assert result['phase'] == 'FAILED' and result['progress_pct'] < 100, result
        if fault == 'hash': assert not any(cmd == 0x1d for _, cmd in model.commands)
        if fault == 'status': assert not any(cmd == 0x22 for _, cmd in model.commands)
        if fault in comm_faults:
            assert result['communication_error'] < 0 and result['failed_node'] in (2, 3), result
            before = list(model.commands); time.sleep(0.8)
            assert model.commands == before and request(port, 'status')[1]['phase'] == 'FAILED'
        if fault in ('preflight_timeout', 'preflight_delayed', 'heater_timeout'):
            assert not any(cmd == 0x1d for _, cmd in model.commands)
        if fault == 'boot_timeout':
            assert model.commands.count((3, 1)) == 4 and not any(cmd == 0x20 for _, cmd in model.commands)
        assert not any(node == 2 and cmd == 0x1d for node, cmd in model.commands)
        return
    assert result['phase'] == 'SUCCEEDED' and result['progress_pct'] == 100, result
    assert [node for node, cmd in model.commands if cmd == 0x20] == [3, 2]
    assert result['mc']['post_boot_id'] != result['mc']['pre_boot_id']
    assert result['th']['written'] == result['th']['size']
    assert bool(result['mc']['warning']) == (fault == 'temperature')


def _stop_processes(processes, logs, model, fds):
    """有序终止子进程与 PTY 模型，并拒绝隐藏退出阶段异常。"""
    master, slave = fds
    shutdown_errors = []
    for process in reversed(processes):
        process.terminate()
        try: process.wait(timeout=12)
        except subprocess.TimeoutExpired: process.kill(); process.wait()
    assert m, f'Missing int32 in dbus-send output: {text}'
    return int(m.group(1))


def _wait_dm_online(deps: Path, address: str, env: dict) -> None:
    """等待 DeviceManager 完成首次 MC/TH 身份与温度采样。"""
    for _ in range(40):
        res = subprocess.run(
            [str(deps / 'bin/dbus-send'), '--session', '--print-reply',
             '--dest=org.aisoc.Device', '/org/aisoc/device',
             'org.aisoc.DeviceInterface.GetVersionInfo'],
            env=dict(env, DBUS_SESSION_BUS_ADDRESS=address),
            capture_output=True, text=True, check=False, timeout=5)
        if res.returncode == 0 and '"status":"ONLINE"' in res.stdout:
            _dbus_call(deps, address, ['--dest=org.aisoc.Device', '/org/aisoc/device',
                                       'org.aisoc.DeviceInterface.RequestImmediateSample', 'string:all'], env)
            time.sleep(0.25)
            return
        time.sleep(0.1)
    raise AssertionError('DeviceManager did not become ONLINE')


def _verify_concurrency_and_estop(deps: Path, address: str, hashes: dict, env: dict):
    """执行空闲急停/解除、OTA 活跃期并发拒 BUSY、维护锁拦截与急停 BUSY 区分。"""
    _wait_dm_online(deps, address, env)
    estop_idle = _extract_first_int32(_dbus_call(
        deps, address, ['--dest=org.aisoc.Device', '/org/aisoc/device',
                        'org.aisoc.DeviceInterface.EmergencyStop', 'byte:1'], env))
    assert estop_idle == 0, f'Idle EmergencyStop expected 0, got {estop_idle}'
    estop_clear = _extract_first_int32(_dbus_call(
        deps, address, ['--dest=org.aisoc.Device', '/org/aisoc/device',
                        'org.aisoc.DeviceInterface.EmergencyStop', 'byte:0'], env))
    assert estop_clear == 0, f'Idle EmergencyStop clear expected 0, got {estop_clear}'
    scan_rc = _extract_first_int32(_dbus_call(
        deps, address, ['--dest=org.aisoc.Forward', '/org/aisoc/forward',
                        'org.aisoc.ForwardInterface.OtaCommand',
                        'byte:0', 'byte:3', 'boolean:false', 'boolean:false', 'string:', 'string:'], env))
    assert scan_rc == 0
    time.sleep(0.25)
    trig_rc = _extract_first_int32(_dbus_call(
        deps, address, ['--dest=org.aisoc.Forward', '/org/aisoc/forward',
                        'org.aisoc.ForwardInterface.OtaCommand',
                        'byte:1', 'byte:3', 'boolean:true', 'boolean:true',
                        f'string:{hashes[2]}', f'string:{hashes[3]}'], env))
    assert trig_rc == 0
    time.sleep(0.1)
    dup_rc = _extract_first_int32(_dbus_call(
        deps, address, ['--dest=org.aisoc.Forward', '/org/aisoc/forward',
                        'org.aisoc.ForwardInterface.OtaCommand',
                        'byte:1', 'byte:1', 'boolean:true', 'boolean:true',
                        f'string:{hashes[2]}', 'string:'], env))
    gcode_rc = _extract_first_int32(_dbus_call(
        deps, address, ['--dest=org.aisoc.Device', '/org/aisoc/device',
                        'org.aisoc.DeviceInterface.ExecuteGcode', 'string:M114'], env))
    home_rc = _extract_first_int32(_dbus_call(
        deps, address, ['--dest=org.aisoc.Device', '/org/aisoc/device',
                        'org.aisoc.DeviceInterface.MotionHome', 'byte:7'], env))
    estop_busy = _extract_first_int32(_dbus_call(
        deps, address, ['--dest=org.aisoc.Device', '/org/aisoc/device',
                        'org.aisoc.DeviceInterface.EmergencyStop', 'byte:1'], env))
    assert dup_rc == -5, f'Concurrent OtaCommand expected -5, got {dup_rc}'
    assert gcode_rc < 0 and home_rc < 0, f'Expected maintenance reject, got gcode={gcode_rc} home={home_rc}'
    assert estop_busy == -5, f'OTA active EmergencyStop expected -5 (BUSY), got {estop_busy}'
    print(json.dumps({'case': 'dec_screen_03_concurrency_estop', 'estop_idle': estop_idle,
                      'estop_clear': estop_clear, 'dup_ota': dup_rc,
                      'gcode': gcode_rc, 'home': home_rc, 'estop_busy': estop_busy}), flush=True)


