/** @file ota_image.cpp
 * @brief 固定目录镜像读取与 ATSG/SHA/CRC 校验；只有 Forward 工作线程调用。
 */
#include "ota_internal.h"
#include "firmware_hash.h"
#include <cstdio>
#include <cstring>
#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>
#include <cerrno>

uint32_t ota_read32(const uint8_t* data) {
    if (data == nullptr) return 0U;
    return static_cast<uint32_t>(data[0]) | (static_cast<uint32_t>(data[1]) << 8U) |
        (static_cast<uint32_t>(data[2]) << 16U) | (static_cast<uint32_t>(data[3]) << 24U);
}
void ota_write32(uint32_t value, uint8_t* data) {
    if (data == nullptr) return;
    for (size_t index = 0U; index < 4U; ++index) data[index] = static_cast<uint8_t>(value >> (index * 8U));
}
/** @brief 将 data/size 的 SHA256 写入 output 的65B十六进制字符串；失败返回假。 */
static bool hash_hex(const uint8_t* data, size_t size, char* output) {
    if (data == nullptr || output == nullptr) return false;
    uint8_t hash[32];
    if (!fw_image_sha256(data, size, hash)) return false;
    for (size_t index = 0U; index < 32U; ++index) std::snprintf(output + index * 2U, 3U, "%02x", hash[index]);
    return true;
}
/** @brief fd 为打开的常规文件，image 为有界缓存；按 fstat 大小读取并拒绝在读期间变化的文件。 */
static bool read_image(int fd, ota_image* image) {
    if (image == nullptr) return false;
    struct stat before = {}, after = {};
    if (fstat(fd, &before) != 0 || !S_ISREG(before.st_mode)) return false;
    if (before.st_size <= 128 || static_cast<uint64_t>(before.st_size) > image->capacity) return false;
    size_t offset = 0U;
    while (offset < static_cast<size_t>(before.st_size)) {
        const auto count = read(fd, image->buffer + offset, static_cast<size_t>(before.st_size) - offset);
        if (count < 0 && errno == EINTR) continue;
        if (count <= 0) return false;
        offset += static_cast<size_t>(count);
    }
    if (fstat(fd, &after) != 0 || after.st_size != before.st_size) return false;
    if (after.st_mtim.tv_sec != before.st_mtim.tv_sec || after.st_mtim.tv_nsec != before.st_mtim.tv_nsec) return false;
    image->size = static_cast<uint32_t>(offset - 128U);
    return true;
}
/** @brief image 为稳定快照，index 为板型0/1；校验尾块、净荷摘要与 ECDSA-P256 签名后生成元数据。 */
static bool verify_image(ota_image* image, uint8_t index, const char** out_error) {
    if (image == nullptr || image->size == 0U) return false;
    const auto* trailer = image->buffer + image->size;
    const uint32_t board = index == 0U ? 0x43500001U : 0x42300001U;
    if (ota_read32(trailer) != 0x41545347U || ota_read32(trailer + 4U) != 0x00010000U) return false;
    if (ota_read32(trailer + 8U) != board || ota_read32(trailer + 16U) != image->size) return false;
    if (fw_image_crc32(trailer, 124U) != ota_read32(trailer + 124U)) return false;
    uint8_t hash[32];
    if (!fw_image_sha256(image->buffer, image->size, hash)) return false;
    if (std::memcmp(hash, trailer + 20U, 32U) != 0) return false;
    char pubkey_path[256];
    if (!fw_image_resolve_pubkey_path(pubkey_path, sizeof(pubkey_path)) ||
        !fw_image_verify_ecdsa_p256(trailer, pubkey_path)) {
        if (out_error != nullptr) *out_error = "PACKAGE_SIGNATURE_INVALID";
        return false;
    }
    image->version = ota_read32(trailer + 12U);
    image->crc = fw_image_crc32(image->buffer, image->size);
    if (!hash_hex(image->buffer, image->size + 128U, image->sha256)) return false;
    image->valid = true;
    return true;
}

bool ota_load_image(fwd_ota_runtime* rt, uint8_t index) {
    if (rt == nullptr || index > 1U) return false;
    auto* image = &rt->image[index];
    image->valid = false;
    image->size = 0U;
    image->sha256[0] = '\0';
    rt->error = "";
    char path[512];
    const char* name = index == 0U ? "fw_mc.bin" : "fw_th.bin";
    const int length = std::snprintf(path, sizeof(path), "%s/%s", rt->owner->firmware_dir, name);
    if (length < 0 || static_cast<size_t>(length) >= sizeof(path)) return false;
    const int fd = open(path, O_RDONLY | O_CLOEXEC | O_NOFOLLOW | O_NONBLOCK);
    if (fd < 0) return false;
    const bool read_ok = read_image(fd, image);
    close(fd);
    const char* verify_err = nullptr;
    if (!read_ok || !verify_image(image, index, &verify_err)) {
        if (verify_err != nullptr) rt->error = verify_err;
        return false;
    }
    if (rt->operation == 1U && std::strcmp(rt->expected[index], image->sha256) != 0) {
        image->valid = false;
        return false;
    }
    return true;
}
