void OtaLocalOverlay::set_lock_hint(const char* text) {
    if (subjects_initialized_ && text != nullptr) lv_subject_copy_string(&lock_estop_subject_, text);
}

void OtaLocalOverlay::sync_from_backend() {
#ifdef HELIX_ENABLE_AISOC
    auto* conn = helix::aisoc::active_aisoc_connection();
    if (!conn || !subjects_initialized_) return;
    const auto st = conn->ota_status();
    const auto snap = conn->snapshot();
    if (st.mc.valid) scanned_mc_sha256_ = st.mc.sha256;
    if (st.th.valid) scanned_th_sha256_ = st.th.sha256;
    const std::string phase_str = format_ota_phase(st);
    const std::string mc_str = format_ota_pkg("fw_mc.bin", st.mc);
    const std::string th_str = format_ota_pkg("fw_th.bin", st.th);
    lv_subject_copy_string(&phase_subject_, phase_str.c_str());
    lv_subject_copy_string(&mc_pkg_subject_, mc_str.c_str());
    lv_subject_copy_string(&th_pkg_subject_, th_str.c_str());
    lv_subject_set_int(&progress_subject_, static_cast<int32_t>(st.progress_pct));
    if (snap.last_estop_outcome == helix::aisoc::AisocEstopOutcome::BACKEND_BUSY ||
        st.last_rpc_code == -5 || st.active || st.maintenance) {
        set_lock_hint("状态: 后台已锁定 (BUSY)");
    } else if (snap.last_estop_outcome == helix::aisoc::AisocEstopOutcome::CONFIRMED ||
               snap.estop_latched) {
        set_lock_hint("状态: 设备已确认急停");
    } else {
        set_lock_hint("状态: 就绪");
    }
#endif
}

void OtaLocalOverlay::handle_scan() {
#ifdef HELIX_ENABLE_AISOC
    auto* conn = helix::aisoc::active_aisoc_connection();
    if (!conn) { ToastManager::instance().show(ToastSeverity::ERROR, "本地设备连接未就绪", 2000); return; }
    helix::aisoc::AisocOtaRequest req;
    req.operation = 0U;
    req.target_mask = 3U;
    conn->request_ota(req);
#endif
}

void OtaLocalOverlay::handle_start_upgrade() {
#ifdef HELIX_ENABLE_AISOC
    auto* conn = helix::aisoc::active_aisoc_connection();
    const uint8_t mask = static_cast<uint8_t>((select_mc_ ? 1U : 0U) | (select_th_ ? 2U : 0U));
    if (!conn || mask == 0U || !confirmed_safe_) {
        ToastManager::instance().show(ToastSeverity::WARNING, "请勾选目标节点并完成安全确认", 2500);
        return;
    }
    if (((mask & 1U) != 0U && scanned_mc_sha256_.empty()) ||
        ((mask & 2U) != 0U && scanned_th_sha256_.empty())) {
        ToastManager::instance().show(ToastSeverity::WARNING, "请先扫描固定目录并通过验签", 2500);
        return;
    }
    helix::aisoc::AisocOtaRequest req;
    req.operation = 1U;
    req.target_mask = mask;
    req.confirmed_safe = true;
    req.allow_reflash = allow_reflash_;
    req.mc_sha256 = scanned_mc_sha256_;
    req.th_sha256 = scanned_th_sha256_;
    conn->request_ota(req);
#endif
}

