/**
 * @brief 将 trailer[52..115] 的 64B (sig_r||sig_s) 编码为 ASN.1 DER ECDSA 签名
 * @param sig_rs 64 字节原始签名（前 32B 为 sig_r，后 32B 为 sig_s）
 * @param out_der 输出 DER 缓冲区（至少 72 字节）
 * @param out_len 输出 DER 总长度
 * @return bool 编码成功且双分量均非零返回 true
 */
static bool encode_ecdsa_der(const uint8_t sig_rs[64], uint8_t out_der[72], size_t* out_len) {
    uint8_t r_buf[36];
    uint8_t s_buf[36];
    size_t r_len = 0U;
    size_t s_len = 0U;
    if (!encode_der_int32(sig_rs, r_buf, &r_len)) return false;
    if (!encode_der_int32(sig_rs + 32U, s_buf, &s_len)) return false;
    const size_t body_len = r_len + s_len;
    out_der[0] = 0x30U;
    out_der[1] = static_cast<uint8_t>(body_len);
    std::memcpy(out_der + 2U, r_buf, r_len);
    std::memcpy(out_der + 2U + r_len, s_buf, s_len);
    *out_len = 2U + body_len;
    return true;
}

/**
 * @brief 解析当前生效的固件验签公钥路径，拒绝来自 /data/ 或 /media/ 的不可信覆盖
 * @param out_path 输出公钥路径缓冲区
 * @param cap 缓冲区容量
 * @return bool 成功写入完整路径返回 true
 */
bool fw_image_resolve_pubkey_path(char* out_path, size_t cap) {
    if (out_path == nullptr || cap == 0U) return false;
    const char* chosen = k_default_pubkey_path;
    const char* env_path = std::getenv("AISOC_OTA_TEST_PUBKEY");
    if (env_path != nullptr && env_path[0] != '\0') {
        const bool in_data = std::strncmp(env_path, "/data/", 6U) == 0 || std::strcmp(env_path, "/data") == 0;
        const bool in_media = std::strncmp(env_path, "/media/", 7U) == 0 || std::strcmp(env_path, "/media") == 0;
        if (!in_data && !in_media) chosen = env_path;
    }
    const int n = std::snprintf(out_path, cap, "%s", chosen);
    return n > 0 && static_cast<size_t>(n) < cap;
}

