/**
 * @brief 基于 OpenSSL 头文件直接校验公钥曲线为 P-256 并执行 EVP_DigestVerify
 * @param trailer 128B ATSG 尾块只读指针
 * @param pubkey_pem_path 公钥 PEM 文件路径
 * @param der 已编码的 ASN.1 DER 签名
 * @param der_len DER 签名字节数
 * @return bool 公钥合法且验签通过返回 true
 */
static bool verify_ecdsa_direct(
    const uint8_t trailer[128],
    const char* pubkey_pem_path,
    const uint8_t* der,
    size_t der_len
) {
    BIO* bio = BIO_new_file(pubkey_pem_path, "r");
    if (bio == nullptr) return false;
    EVP_PKEY* pkey = PEM_read_bio_PUBKEY(bio, nullptr, nullptr, nullptr);
    BIO_free(bio);
    if (pkey == nullptr) return false;
    bool ok = false;
    const EC_KEY* ec = (EVP_PKEY_base_id(pkey) == k_evp_pkey_ec) ? EVP_PKEY_get0_EC_KEY(pkey) : nullptr;
    const EC_GROUP* grp = (ec != nullptr) ? EC_KEY_get0_group(ec) : nullptr;
    if (grp != nullptr && EC_GROUP_get_curve_name(grp) == k_nid_prime256v1) {
        EVP_MD_CTX* ctx = EVP_MD_CTX_new();
        if (ctx != nullptr) {
            ok = EVP_DigestVerifyInit(ctx, nullptr, EVP_sha256(), nullptr, pkey) == 1 &&
                 EVP_DigestUpdate(ctx, trailer, 52U) == 1 &&
                 EVP_DigestVerifyFinal(ctx, der, der_len) == 1;
            EVP_MD_CTX_free(ctx);
        }
    }
    EVP_PKEY_free(pkey);
    return ok;
}

