#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MCU 固件 128B ATSG 尾块 ECDSA-P256 签发与验签工具（DEC-SCREEN-08=B）。

仅依赖 Python 标准库与系统 /usr/bin/openssl CLI（不依赖第三方 cryptography 库）。
签名覆盖 128B ATSG 尾块前 52 字节（magic+struct_version+board_id+version_code+
payload_len+payload_sha256），将 32B 大端 sig_r 与 32B 大端 sig_s 写入 trailer[52:116]，
清零 reserved[8] 并重算 trailer[0:124] 的 IEEE CRC32 写入 trailer[124:128]。
边界声明：boot/bootloadermc 保持冻结 0 改动，MC FAT32 U 盘直接救援通道无 ECDSA 校验边界。
"""

from __future__ import annotations

import argparse
import hashlib
from pathlib import Path
import shutil
import struct
import subprocess
import sys
import tempfile
import zlib

ATSG_MAGIC = 0x41545347
ATSG_STRUCT_VERSION = 0x00010000
VALID_BOARD_IDS = (0x43500001, 0x42300001)
TRAILER_BYTES = 128
SIGNED_HEADER_BYTES = 52


def _openssl_bin() -> str:
    """解析系统中可用的 openssl 可执行路径，优先 /usr/bin/openssl。"""
    if Path("/usr/bin/openssl").is_file():
        return "/usr/bin/openssl"
    found = shutil.which("openssl")
    if not found:
        raise RuntimeError("系统未找到 openssl 可执行文件")
    return found


def _read_der_int(data: bytes, pos: int) -> tuple[bytes, int]:
    """从 ASN.1 DER 字节流 pos 处解析单个正整数并归一化为 32 字节大端定长。"""
    if pos + 2 > len(data) or data[pos] != 0x02:
        raise ValueError("DER 签名缺少 INTEGER 标签")
    length = data[pos + 1]
    end = pos + 2 + length
    if length == 0 or end > len(data):
        raise ValueError("DER INTEGER 长度越界")
    raw = data[pos + 2 : end]
    if raw[0] == 0x00 and len(raw) > 1:
        raw = raw[1:]
    if len(raw) > 32 or not any(raw):
        raise ValueError("ECDSA 分量长度非法或全零")
    return raw.rjust(32, b"\x00"), end


def der_to_raw_rs(der: bytes) -> tuple[bytes, bytes]:
    """将 ASN.1 DER ECDSA 签名解析为 (32B sig_r, 32B sig_s) 大端字节串。"""
    if len(der) < 8 or der[0] != 0x30:
        raise ValueError("DER 签名缺少 SEQUENCE 标签")
    seq_len = der[1]
    if 2 + seq_len != len(der):
        raise ValueError("DER SEQUENCE 长度不匹配")
    sig_r, next_pos = _read_der_int(der, 2)
    sig_s, end_pos = _read_der_int(der, next_pos)
    if end_pos != len(der):
        raise ValueError("DER 签名尾部存在多余字节")
    return sig_r, sig_s


def _encode_der_int(val: bytes) -> bytes:
    """将 32 字节无符号大端整数编码为合法的 ASN.1 DER INTEGER。"""
    stripped = val.lstrip(b"\x00")
    if not stripped:
        raise ValueError("ECDSA 签名分量全零，拒绝编码")
    if stripped[0] & 0x80:
        stripped = b"\x00" + stripped
    return bytes((0x02, len(stripped))) + stripped


def raw_rs_to_der(sig_r: bytes, sig_s: bytes) -> bytes:
    """将 32B sig_r 与 32B sig_s 大端字节串编码为 ASN.1 DER ECDSA 签名。"""
    if len(sig_r) != 32 or len(sig_s) != 32:
        raise ValueError("sig_r 与 sig_s 必须各为 32 字节")
    body = _encode_der_int(sig_r) + _encode_der_int(sig_s)
    return bytes((0x30, len(body))) + body


def validate_atsg_base(data: bytes, check_crc: bool) -> tuple[bytes, bytearray]:
    """校验固件镜像的 ATSG 魔数、结构版本、板型、净荷长度、SHA-256 及可选尾块 CRC32。"""
    if len(data) <= TRAILER_BYTES:
        raise ValueError("固件长度不足 128B ATSG 尾块要求")
    payload = data[:-TRAILER_BYTES]
    trailer = bytearray(data[-TRAILER_BYTES:])
    magic, ver, board_id, _fw_ver, payload_len = struct.unpack_from("<5I", trailer, 0)
    if magic != ATSG_MAGIC or ver != ATSG_STRUCT_VERSION:
        raise ValueError("ATSG 魔数或结构版本不合法")
    if board_id not in VALID_BOARD_IDS or payload_len != len(payload):
        raise ValueError("ATSG 板型 ID 或净荷长度不匹配")
    if hashlib.sha256(payload).digest() != bytes(trailer[20:52]):
        raise ValueError("净荷 SHA-256 与 ATSG 尾块不一致")
    if check_crc:
        expected_crc = struct.unpack_from("<I", trailer, 124)[0]
        if (zlib.crc32(trailer[:124]) & 0xFFFFFFFF) != expected_crc:
            raise ValueError("ATSG 尾块 CRC32 校验失败")
    return payload, trailer


