def build_raw_package(directory: Path, node: int) -> Path:
    """生成固定板型的未签名 ATSG 包，返回文件路径。"""
    image = bytes(range(256)) * 5 + b'last'
    trailer = bytearray(128)
    struct.pack_into('<5I', trailer, 0, 0x41545347, 0x10000,
                     0x43500001 if node == 2 else 0x42300001, 0x02000001, len(image))
    trailer[20:52] = hashlib.sha256(image).digest()
    struct.pack_into('<I', trailer, 124, zlib.crc32(trailer[:124]) & 0xFFFFFFFF)
    out = directory / ('fw_mc.bin' if node == 2 else 'fw_th.bin')
    out.write_bytes(image + bytes(trailer))
    return out


def prepare_packages(root: Path, directory: Path, fault: str, priv_key: Path) -> dict:
    """根据测试场景生成合法签名、未签名全零或坏签名/篡改包，返回 SHA-256 映射。"""
    signer = root / 'tools/sign_mcu_firmware.py'
    hashes = {}
    for node in (2, 3):
        raw_path = build_raw_package(directory, node)
        if fault != 'unsigned_zero':
            subprocess.run([sys.executable, str(signer), '--key', str(priv_key),
                            '--input', str(raw_path), '--output', str(raw_path)], check=True)
        if fault == 'bad_signature' and node == 2:
            buf = bytearray(raw_path.read_bytes())
            buf[-128 + 52] ^= 0x01
            struct.pack_into('<I', buf, len(buf) - 4, zlib.crc32(buf[-128:-4]) & 0xFFFFFFFF)
            raw_path.write_bytes(bytes(buf))
        elif fault == 'tampered_payload' and node == 3:
            buf = bytearray(raw_path.read_bytes())
            buf[10] ^= 0x55
            buf[-128 + 20:-128 + 52] = hashlib.sha256(buf[:-128]).digest()
            struct.pack_into('<I', buf, len(buf) - 4, zlib.crc32(buf[-128:-4]) & 0xFFFFFFFF)
            raw_path.write_bytes(bytes(buf))
        hashes[node] = hashlib.sha256(raw_path.read_bytes()).hexdigest()
    return hashes


